CREATE TABLE IF NOT EXISTS schema_migrations (version text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE users (id uuid PRIMARY KEY, display_name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE identities (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), issuer text NOT NULL, subject text NOT NULL, UNIQUE(issuer, subject));
CREATE TABLE sessions (token_hash text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX sessions_expiry ON sessions(expires_at);
CREATE TABLE role_assignments (user_id uuid REFERENCES users(id), role text NOT NULL CHECK(role IN ('buyer','author','moderator','editor','support','finance','admin')), PRIMARY KEY(user_id,role));
CREATE TABLE capabilities (name text PRIMARY KEY, enabled boolean NOT NULL DEFAULT false);
INSERT INTO capabilities(name) VALUES ('suite_sales'),('cloud_sales'),('community_uploads');
CREATE TABLE applications (id text PRIMARY KEY, name text NOT NULL, status text NOT NULL DEFAULT 'development' CHECK(status IN ('planned','development','experimental','available')), content jsonb NOT NULL);
CREATE TABLE regional_prices (id uuid PRIMARY KEY, country char(2) NOT NULL, currency char(3) NOT NULL, amount bigint NOT NULL CHECK(amount>0), version integer NOT NULL DEFAULT 1, approved boolean NOT NULL DEFAULT false, provider text NOT NULL CHECK(provider IN ('stripe','asaas')), terms_version text, starts_at timestamptz NOT NULL DEFAULT now(), ends_at timestamptz, UNIQUE(country, version));
CREATE TABLE orders (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT, price_id uuid NOT NULL REFERENCES regional_prices(id), amount bigint NOT NULL, currency char(3) NOT NULL, country char(2) NOT NULL, provider text NOT NULL, environment text NOT NULL DEFAULT 'sandbox', status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','processing','paid','failed','cancelled','refunded','partially_refunded','disputed','duplicate_review')), price_snapshot jsonb NOT NULL, terms_version text NOT NULL, idempotency_key text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,idempotency_key));
CREATE INDEX orders_user ON orders(user_id,created_at DESC);
CREATE TABLE payment_attempts (id uuid PRIMARY KEY, order_id uuid NOT NULL REFERENCES orders(id), provider text NOT NULL, provider_id text, status text NOT NULL DEFAULT 'creating', checkout_url text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(provider,provider_id), UNIQUE(order_id));
CREATE TABLE payment_event_inbox (id uuid PRIMARY KEY, provider text NOT NULL, environment text NOT NULL, event_id text NOT NULL, payload jsonb NOT NULL, status text NOT NULL DEFAULT 'pending', attempts integer NOT NULL DEFAULT 0, next_attempt_at timestamptz NOT NULL DEFAULT now(), last_error text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(provider,environment,event_id));
CREATE INDEX inbox_pending ON payment_event_inbox(status,next_attempt_at);
CREATE TABLE suite_entitlements (id uuid PRIMARY KEY, user_id uuid NOT NULL UNIQUE REFERENCES users(id) ON DELETE RESTRICT, order_id uuid NOT NULL UNIQUE REFERENCES orders(id), status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','disputed','revoked')), granted_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE license_credentials (id uuid PRIMARY KEY, entitlement_id uuid NOT NULL REFERENCES suite_entitlements(id), encrypted_key text NOT NULL, fingerprint text NOT NULL UNIQUE, encryption_version text NOT NULL, status text NOT NULL DEFAULT 'active', created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX one_active_credential ON license_credentials(entitlement_id) WHERE status='active';
CREATE TABLE devices (id uuid PRIMARY KEY, entitlement_id uuid NOT NULL REFERENCES suite_entitlements(id), public_key text NOT NULL, name text NOT NULL, status text NOT NULL DEFAULT 'active', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(entitlement_id,public_key));
CREATE TABLE activations (id uuid PRIMARY KEY, device_id uuid NOT NULL REFERENCES devices(id), application_id text NOT NULL REFERENCES applications(id), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(device_id,application_id));
CREATE TABLE audit_events (id uuid PRIMARY KEY, actor_id uuid REFERENCES users(id), action text NOT NULL, object_id text NOT NULL, result text NOT NULL DEFAULT 'success', context jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE outbox_events (id uuid PRIMARY KEY, kind text NOT NULL, payload jsonb NOT NULL, status text NOT NULL DEFAULT 'pending', attempts integer NOT NULL DEFAULT 0, next_attempt_at timestamptz NOT NULL DEFAULT now(), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE releases (id uuid PRIMARY KEY, application_id text NOT NULL REFERENCES applications(id), version text NOT NULL, channel text NOT NULL, architecture text NOT NULL DEFAULT 'x86_64', status text NOT NULL DEFAULT 'draft', requirements jsonb NOT NULL DEFAULT '{}', notes text NOT NULL DEFAULT '', published_at timestamptz, UNIQUE(application_id,version,channel));
CREATE TABLE release_artifacts (id uuid PRIMARY KEY, release_id uuid NOT NULL REFERENCES releases(id), object_key text NOT NULL, byte_size bigint NOT NULL CHECK(byte_size>0), sha256 char(64) NOT NULL, signature text NOT NULL, verified boolean NOT NULL DEFAULT false);
CREATE TABLE community_packages (id uuid PRIMARY KEY, author_id uuid NOT NULL REFERENCES users(id), kind text NOT NULL CHECK(kind IN ('plugin','template','resource')), application_id text NOT NULL REFERENCES applications(id), name text NOT NULL, original_locale text NOT NULL, status text NOT NULL DEFAULT 'draft', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE package_versions (id uuid PRIMARY KEY, package_id uuid NOT NULL REFERENCES community_packages(id), version text NOT NULL, manifest jsonb NOT NULL, quarantine_key text NOT NULL, sha256 char(64) NOT NULL, status text NOT NULL DEFAULT 'quarantine', UNIQUE(package_id,version));
CREATE TABLE moderation_reviews (id uuid PRIMARY KEY, package_id uuid NOT NULL REFERENCES community_packages(id), reviewer_id uuid NOT NULL REFERENCES users(id), decision text NOT NULL, note text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE cloud_plans (id uuid PRIMARY KEY, name text NOT NULL, approved boolean NOT NULL DEFAULT false, quota_bytes bigint, retention_days integer);
CREATE TABLE cloud_subscriptions (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), plan_id uuid NOT NULL REFERENCES cloud_plans(id), status text NOT NULL, provider_id text UNIQUE);
CREATE TABLE workspaces (id uuid PRIMARY KEY, owner_id uuid NOT NULL REFERENCES users(id), name text NOT NULL);
CREATE TABLE workspace_members (workspace_id uuid REFERENCES workspaces(id), user_id uuid REFERENCES users(id), role text NOT NULL, PRIMARY KEY(workspace_id,user_id));
CREATE TABLE doc_pages (id uuid PRIMARY KEY, slug text NOT NULL, locale text NOT NULL, title text NOT NULL, body text NOT NULL, status text NOT NULL DEFAULT 'draft', revision integer NOT NULL DEFAULT 1, translation_review text NOT NULL DEFAULT 'pending', UNIQUE(slug,locale));
CREATE TABLE content_revisions (id uuid PRIMARY KEY, page_id uuid NOT NULL REFERENCES doc_pages(id), actor_id uuid NOT NULL REFERENCES users(id), content jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE support_tickets (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), subject text NOT NULL, body text NOT NULL, status text NOT NULL DEFAULT 'open', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE rate_limits (bucket text NOT NULL, window_start bigint NOT NULL, hits integer NOT NULL DEFAULT 1, PRIMARY KEY(bucket,window_start));
